import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DMenu from "discourse/float-kit/components/d-menu";
import DTooltip from "discourse/float-kit/components/d-tooltip";
import { deferAnonymousAction } from "discourse/lib/anonymous-action";
import getURL from "discourse/lib/get-url";
import { NotificationLevels } from "discourse/lib/notification-levels";
import { applyBehaviorTransformer } from "discourse/lib/transformer";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class VoteButton extends Component {
  @service currentUser;

  @tracked hasVoted = false;
  @tracked hasSeenSuccessMenu = false;

  get topic() {
    return this.args.topic;
  }

  get buttonIcon() {
    return this.topic.user_voted ? "vote-up-filled" : "vote-up";
  }

  get isWatching() {
    return (
      this.topic.details?.notification_level === NotificationLevels.WATCHING
    );
  }

  get limitsEnabled() {
    return this.currentUser?.vote_limit != null;
  }

  get showVotedMenu() {
    return this.hasVoted && !this.hasSeenSuccessMenu;
  }

  get showVotedActions() {
    return this.showVotedMenu || this.topic.user_voted;
  }

  get buttonClasses() {
    if (this.currentUser?.vote_limit === 0) {
      return "btn-default btn-small voting-wrapper__button";
    }

    return this.topic.user_voted
      ? "btn-success btn-small voting-wrapper__button"
      : "btn-default btn-small voting-wrapper__button";
  }

  get ariaLabel() {
    if (this.topic.closed) {
      return i18n("topic_voting.voting_closed_description");
    }
    if (this.currentUser?.vote_limit === 0) {
      return i18n("topic_voting.locked_description");
    }
    return this.topic.user_voted
      ? i18n("topic_voting.remove_vote")
      : i18n("topic_voting.vote_title");
  }

  @action
  onShowMenu() {
    if (!this.topic.user_voted) {
      this.hasVoted = false;
      this.hasSeenSuccessMenu = false;
    }

    applyBehaviorTransformer("topic-vote-button-click", async () => {
      if (!this.currentUser) {
        if (this.topic.archived || this.topic.closed) {
          return;
        }
        return deferAnonymousAction(this, "vote_topic", {
          topic_id: this.topic.id,
        });
      }

      if (this.currentUser.vote_limit === 0) {
        return;
      }

      if (
        !this.topic.closed &&
        !this.topic.user_voted &&
        !this.currentUser.votes_exceeded
      ) {
        this.args.addVote();
        this.hasVoted = true;
      }
    });
  }

  @action
  removeVote() {
    this.args.removeVote();
    this.hasVoted = false;
    this.hasSeenSuccessMenu = false;
    this.dMenu.close();
  }

  @action
  async toggleWatching() {
    const newLevel = this.isWatching
      ? NotificationLevels.REGULAR
      : NotificationLevels.WATCHING;
    await this.topic.details.updateNotifications(newLevel);
  }

  @action
  onRegisterApi(api) {
    this.dMenu = api;
  }

  @action
  onCloseMenu() {
    if (this.hasVoted && !this.hasSeenSuccessMenu) {
      this.hasSeenSuccessMenu = true;
    }
  }

  <template>
    {{#if this.topic.closed}}
      <DTooltip @identifier="vote-closed-tooltip" @placement="right">
        <:trigger>
          <DButton
            class={{this.buttonClasses}}
            @disabled={{true}}
            @icon={{this.buttonIcon}}
            @translatedAriaLabel={{this.ariaLabel}}
          />
        </:trigger>
        <:content>
          {{i18n "topic_voting.voting_closed_description"}}
        </:content>
      </DTooltip>
    {{else if this.currentUser}}
      <DMenu
        class={{this.buttonClasses}}
        @ariaLabel={{this.ariaLabel}}
        @icon={{this.buttonIcon}}
        @identifier="topic-voting-menu"
        @onClose={{this.onCloseMenu}}
        @onRegisterApi={{this.onRegisterApi}}
        @onShow={{this.onShowMenu}}
        @placement="right"
        @title={{this.ariaLabel}}
      >
        <:content>
          <DDropdownMenu as |dropdown|>
            {{#if (eq this.currentUser.vote_limit 0)}}
              <dropdown.item class="topic-voting-menu__title --locked">
                {{dIcon "lock"}}
                <span>{{i18n "topic_voting.locked_description"}}</span>
              </dropdown.item>
            {{else}}
              {{#if this.limitsEnabled}}
                <dropdown.item class="topic-voting-menu__votes-left">
                  <DButton
                    class="btn-transparent see-votes topic-voting-menu__row-btn"
                    @href={{getURL "/my/activity/votes"}}
                    @icon="check-to-slot"
                    @translatedLabel={{i18n
                      "topic_voting.see_votes"
                      count=this.currentUser.votes_left
                      max=this.currentUser.vote_limit
                    }}
                  />
                </dropdown.item>
              {{/if}}
              {{#if this.showVotedActions}}
                <dropdown.item class="topic-voting-menu__row">
                  <DButton
                    class="btn-transparent remove-vote topic-voting-menu__row-btn"
                    @action={{this.removeVote}}
                    @icon="arrow-rotate-left"
                    @translatedLabel={{i18n "topic_voting.remove_vote"}}
                  />
                </dropdown.item>
                <dropdown.item class="topic-voting-menu__watch-toggle">
                  <DButton
                    class="btn-transparent topic-voting-menu__row-btn"
                    @action={{this.toggleWatching}}
                    @icon={{if this.isWatching "toggle-on" "toggle-off"}}
                    @translatedLabel={{i18n "topic_voting.watch_topic"}}
                  />
                </dropdown.item>
              {{/if}}
            {{/if}}
          </DDropdownMenu>
        </:content>
      </DMenu>
    {{else}}
      <DButton
        class={{this.buttonClasses}}
        @action={{this.onShowMenu}}
        @icon={{this.buttonIcon}}
        @translatedAriaLabel={{this.ariaLabel}}
        @translatedTitle={{this.ariaLabel}}
      />
    {{/if}}
  </template>
}
import { i18n } from "discourse-i18n";

const VoteCountTrigger = <template>
  <button
    aria-label={{i18n "topic_voting.show_voters"}}
    type="button"
    ...attributes
  >
    {{yield}}
  </button>
</template>;

export default VoteCountTrigger;
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { service } from "@ember/service";
import DMenu from "discourse/float-kit/components/d-menu";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { bind } from "discourse/lib/decorators";
import getURL from "discourse/lib/get-url";
import dBoundAvatarTemplate from "discourse/ui-kit/helpers/d-bound-avatar-template";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";
import VoteCountTrigger from "./vote-count-trigger.gjs";

export default class VoteCount extends Component {
  @service siteSettings;
  @service currentUser;

  @tracked voters = null;
  @tracked lastVoteCount = null;
  @tracked totalVoters = 0;
  @tracked isLoading = false;

  get showVoterMenu() {
    return this.siteSettings.topic_voting_show_who_voted && this.currentUser;
  }

  get displayCount() {
    const count = this.args.topic.vote_count;
    if (count >= 1000) {
      const thousands = (count / 1000).toFixed(1).replace(/\.0$/, "");
      return i18n("topic_voting.vote_count_thousands", { count: thousands });
    }
    return count;
  }

  get remainingVoters() {
    return Math.max(this.totalVoters - (this.voters?.length || 0), 0);
  }

  get hasOverflowVoters() {
    return this.remainingVoters > 0;
  }

  @bind
  async loadVoters() {
    // Clear cache if vote count changed
    if (
      this.lastVoteCount !== null &&
      this.lastVoteCount !== this.args.topic.vote_count
    ) {
      this.voters = null;
    }

    if (this.voters) {
      return;
    }

    this.lastVoteCount = this.args.topic.vote_count;
    this.isLoading = true;

    try {
      const users = await ajax("/voting/who", {
        type: "GET",
        data: { topic_id: this.args.topic.id },
      });

      this.totalVoters = this.args.topic.vote_count;
      this.voters = users.map((user) => ({
        template: user.avatar_template,
        username: user.username,
        url: getURL("/u/") + user.username.toLowerCase(),
      }));
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.isLoading = false;
    }
  }

  <template>
    {{#if this.showVoterMenu}}
      <DMenu
        class={{dConcatClass
          "voting-wrapper__count"
          (if (eq @topic.vote_count 0) "no-votes")
        }}
        @identifier="vote-count-voters"
        @modalForMobile={{true}}
        @onShow={{this.loadVoters}}
        @placement="right"
        @triggerComponent={{VoteCountTrigger}}
      >
        <:trigger>
          <span class="voting-wrapper__count-text">{{this.displayCount}}</span>
        </:trigger>
        <:content>
          {{#if this.isLoading}}
            <div class="voting-voters__loading">
              {{i18n "loading"}}
            </div>
          {{else if (eq @topic.vote_count 0)}}
            <div class="voting-voters__empty">
              {{i18n "topic_voting.no_votes_yet"}}
            </div>
          {{else if this.voters}}
            <div class="voting-voters__list">
              {{#each this.voters as |voter|}}
                <a
                  class="voting-voters__avatar trigger-user-card"
                  data-user-card={{voter.username}}
                  title={{voter.username}}
                >
                  {{dBoundAvatarTemplate voter.template "small"}}
                </a>
              {{/each}}
              {{#if this.hasOverflowVoters}}
                <div class="voting-voters__overflow">
                  {{i18n
                    "topic_voting.and_more_voters"
                    count=this.remainingVoters
                  }}
                </div>
              {{/if}}
            </div>
          {{/if}}
        </:content>
      </DMenu>
    {{else}}
      <div
        class={{dConcatClass
          "voting-wrapper__count"
          (if (eq @topic.vote_count 0) "no-votes")
        }}
      >
        <div class="voting-wrapper__count-text">
          {{this.displayCount}}
        </div>
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import VoteButton from "./vote-button.gjs";
import VoteCount from "./vote-count.gjs";

export default class VoteBox extends Component {
  @service currentUser;

  @action
  addVote() {
    return this.#sendVote("/voting/vote", true);
  }

  @action
  removeVote() {
    return this.#sendVote("/voting/unvote", false);
  }

  #sendVote(url, userVoted) {
    const topic = this.args.topic;

    return ajax(url, {
      type: "POST",
      data: {
        topic_id: topic.id,
      },
    })
      .then((result) => {
        topic.vote_count = result.vote_count;
        topic.user_voted = userVoted;
        this.currentUser.votes_exceeded = !result.can_vote;
        this.currentUser.vote_limit = result.vote_limit;
        this.currentUser.votes_left = result.votes_left;
      })
      .catch(popupAjaxError);
  }

  <template>
    <div class="voting-wrapper">
      <VoteButton
        @addVote={{this.addVote}}
        @removeVote={{this.removeVote}}
        @topic={{@topic}}
      />
      <VoteCount @topic={{@topic}} />
    </div>
  </template>
}
import VoteBox from "../../components/vote-box.gjs";

export default <template>
  {{#if @outletArgs.topic.can_vote}}
    <div class="voting header-title-voting">
      <VoteBox @topic={{@outletArgs.topic}} />
    </div>
  {{/if}}
</template>
import VoteBox from "../../components/vote-box.gjs";

export default <template>
  {{#let @outletArgs.model as |topic|}}
    {{#if
      (and
        topic.can_vote
        (or
          topic.is_nested_view
          (and topic.postStream.loaded topic.postStream.firstPostPresent)
        )
      )
    }}
      <div class="voting title-voting">
        <VoteBox @topic={{topic}} />
      </div>
    {{/if}}
  {{/let}}
</template>
import Component from "@glimmer/component";
import { LinkTo } from "@ember/routing";
import { service } from "@ember/service";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class UserVotedTopics extends Component {
  @service siteSettings;

  <template>
    {{#if this.siteSettings.topic_voting_show_votes_on_profile}}
      <li class="user-nav__activity-votes">

        <LinkTo @route="userActivity.votes">
          {{dIcon "check-to-slot" aria-hidden="true"}}
          {{i18n "topic_voting.vote_title_plural"}}
        </LinkTo>
      </li>
    {{/if}}
  </template>
}
import { withPluginApi } from "discourse/lib/plugin-api";
import NavItem from "discourse/models/nav-item";
import { i18n } from "discourse-i18n";

export default {
  name: "discourse-topic-voting",

  initialize() {
    withPluginApi((api) => {
      api.addUserNavSidebarLink("activity", {
        name: "activity-votes",
        route: "userActivity.votes",
        label: "topic_voting.vote_title_plural",
        icon: "check-to-slot",
        displayed: ({ siteSettings }) =>
          siteSettings.topic_voting_show_votes_on_profile,
      });

      api.replaceIcon("topic_voting.voting_closed", "lock");

      api.registerNotificationTypeRenderer(
        "votes_released",
        (NotificationTypeBase) => {
          return class extends NotificationTypeBase {
            get label() {
              return this.siteSettings.topic_voting_enable_vote_limits
                ? i18n("topic_voting.notification_label.vote_released")
                : i18n("topic_voting.notification_label.voting_closed");
            }

            get linkTitle() {
              return this.label;
            }

            get icon() {
              return this.siteSettings.topic_voting_enable_vote_limits
                ? super.icon
                : "topic_voting.voting_closed";
            }
          };
        }
      );

      const siteSettings = api.container.lookup("service:site-settings");
      if (siteSettings.topic_voting_enabled) {
        api.registerValueTransformer(
          "navigation-items",
          ({ value, context }) => {
            if (context.category?.can_vote) {
              const hotItem = value.find((item) => item.name === "hot");
              if (hotItem) {
                hotItem.title = i18n("topic_voting.hot_nav_help");
              }
            }
            return value;
          }
        );

        const pageSearchController = api.container.lookup(
          "controller:full-page-search"
        );
        pageSearchController.sortOrders.push({
          name: i18n("search.most_votes"),
          id: 5,
          term: "order:votes",
        });

        const addVotingNavItem = (name, param, { requiresUser } = {}) => {
          const [key, value] = param.split("=");
          api.addNavigationBarItem({
            name,
            before: "top",
            customFilter: (category) =>
              category?.can_vote && (!requiresUser || api.getCurrentUser()),
            customHref: (_category, args) =>
              `${NavItem.pathFor("latest", args)}?${param}`,
            forceActive: (_category, _args, router) => {
              const queryParams = router.currentRoute.queryParams;
              return (
                queryParams &&
                Object.keys(queryParams).length === 1 &&
                queryParams[key] === value
              );
            },
          });
        };

        addVotingNavItem("votes", "order=votes");
        addVotingNavItem("my_votes", "state=my_votes", {
          requiresUser: true,
        });

        api.addSearchSuggestion("order:votes");
      }

      api.registerValueTransformer(
        "category-available-views",
        ({ value, context }) => {
          if (context.customFields.enable_topic_voting) {
            value.push({
              name: i18n("filters.votes.title"),
              value: "votes",
            });
          }
        }
      );
    });
  },
};
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-topic-voting";

export default {
  name: "topic-voting-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "check-to-slot");
    });
  },
};
import { computed, get } from "@ember/object";
import { withPluginApi } from "discourse/lib/plugin-api";
import Category from "discourse/models/category";
import { i18n } from "discourse-i18n";

function extendCategory(api) {
  Category.reopen({
    enable_topic_voting: computed("custom_fields.enable_topic_voting", {
      get() {
        return get(this.custom_fields, "enable_topic_voting") === true;
      },
    }),
  });
  api.addPostClassesCallback((post) => {
    if (post.post_number === 1 && post.can_vote) {
      return ["voting-post"];
    }
  });
  api.addTrackedPostProperties("can_vote");
  api.addTagsHtmlCallback(
    (topic) => {
      const router = api.container.lookup("service:router");

      if (!topic.can_vote || router.currentRouteName?.startsWith("topic.")) {
        return;
      }

      let buffer = [];

      let title = "";
      if (topic.user_voted) {
        title = ` title='${i18n("topic_voting.voted")}'`;
      }

      let userVotedClass = topic.user_voted ? " voted" : "";
      buffer.push(
        `<a href='${topic.url}' class='list-vote-count vote-count-${topic.vote_count} discourse-tag simple${userVotedClass}'${title}>`
      );

      buffer.push(i18n("topic_voting.votes", { count: topic.vote_count }));
      buffer.push("</a>");

      return buffer.join("");
    },
    { priority: -100 }
  );

  api.addModelField("topic", "vote_count");
  api.addModelField("topic", "user_voted");
  api.addModelField("user", "votes_exceeded");
  api.addModelField("user", "vote_limit");
  api.addModelField("user", "votes_left");
}

export default {
  name: "extend-category-for-voting",

  before: "inject-discourse-objects",

  initialize() {
    withPluginApi((api) => {
      extendCategory(api);
      api.addCategorySortCriteria("votes");
    });
  },
};
import { withPluginApi } from "discourse/lib/plugin-api";

export default {
  name: "discourse-topic-voting-transformers",
  before: "freeze-valid-transformers",

  initialize() {
    withPluginApi((api) => {
      api.addBehaviorTransformerName("topic-vote-button-click");
    });
  },
};
import UserAction from "discourse/models/user-action";
import UserTopicListRoute from "discourse/routes/user-topic-list";
import { i18n } from "discourse-i18n";

export default class UserActivityVotes extends UserTopicListRoute {
  userActionType = UserAction.TYPES.topics;

  model() {
    return this.store
      .findFiltered("topicList", {
        filter:
          "topics/voted-by/" + this.modelFor("user").get("username_lower"),
      })
      .then((model) => {
        model.set("emptyState", this.emptyState());
        return model;
      });
  }

  emptyState() {
    const user = this.modelFor("user");
    const title = this.isCurrentUser(user)
      ? i18n("topic_voting.no_votes_title_self")
      : i18n("topic_voting.no_votes_title_others", {
          username: user.username,
        });

    return {
      title,
      body: "",
    };
  }
}
export default {
  resource: "user",
  path: "users/:username",
  map() {
    this.route(
      "userActivity",
      { path: "activity", resetNamespace: true },
      function () {
        this.route("votes");
      }
    );
  },
};
import * as Mod1 from "./discourse/components/vote-box";
import * as Mod2 from "./discourse/components/vote-button";
import * as Mod3 from "./discourse/components/vote-count-trigger";
import * as Mod4 from "./discourse/components/vote-count";
import * as Mod5 from "./discourse/connectors/header-topic-info__before/header-topic-voting.gjs";
import * as Mod6 from "./discourse/connectors/topic-title/topic-title-voting.gjs";
import * as Mod7 from "./discourse/connectors/user-activity-bottom/user-voted-topics.gjs";
import * as Mod8 from "./discourse/initializers/discourse-topic-voting";
import * as Mod9 from "./discourse/initializers/topic-voting-admin-plugin-configuration-nav";
import * as Mod10 from "./discourse/model-types";
import * as Mod11 from "./discourse/pre-initializers/extend-category-for-voting";
import * as Mod12 from "./discourse/pre-initializers/transformers";
import * as Mod13 from "./discourse/routes/user-activity/votes";
import * as Mod14 from "./discourse/topic-voting-route-map";
const compatModules = {
  "discourse/components/vote-box": Mod1,
  "discourse/components/vote-button": Mod2,
  "discourse/components/vote-count-trigger": Mod3,
  "discourse/components/vote-count": Mod4,
  "discourse/connectors/header-topic-info__before/header-topic-voting": Mod5,
  "discourse/connectors/topic-title/topic-title-voting": Mod6,
  "discourse/connectors/user-activity-bottom/user-voted-topics": Mod7,
  "discourse/initializers/discourse-topic-voting": Mod8,
  "discourse/initializers/topic-voting-admin-plugin-configuration-nav": Mod9,
  "discourse/model-types": Mod10,
  "discourse/pre-initializers/extend-category-for-voting": Mod11,
  "discourse/pre-initializers/transformers": Mod12,
  "discourse/routes/user-activity/votes": Mod13,
  "discourse/topic-voting-route-map": Mod14,
};
export { compatModules };
export default compatModules;
